begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;select plan(14);
select ok((select rowsecurity from pg_tables where schemaname='public' and tablename='student_save_requests'),'Student request receipts enforce RLS');
select ok(not has_table_privilege('authenticated','public.student_save_requests','select'),'Request payloads are not exposed to clients');
create temporary table student_scope(label text primary key,id uuid);grant select,insert on student_scope to authenticated;
insert into auth.users(id,email) values('99999400-0000-0000-0000-000000000001','native-student-first@example.test');
set local role authenticated;set local request.jwt.claim.sub='99999400-0000-0000-0000-000000000001';
insert into student_scope select 'tenant',public.create_business('Native student first');
insert into student_scope select 'branch',id from public.branches limit 1;
insert into student_scope select 'student',public.save_student((select id from student_scope where label='tenant'),'99999400-0000-0000-0000-000000000010',null,'{"first_name":"Native student","phone":"998903331111"}','{}',array[(select id from student_scope where label='branch')]);
select is((select customer_id from public.student_profiles where tenant_id=(select id from student_scope where label='tenant')),(select id from student_scope where label='student'),'Student profile uses shared customer identity');
select is((select count(*)::integer from public.customers where tenant_id=(select id from student_scope where label='tenant')),1,'One form creates one person');
select is(public.save_student((select id from student_scope where label='tenant'),'99999400-0000-0000-0000-000000000010',null,'{"first_name":"Native student","phone":"998903331111"}','{}',array[(select id from student_scope where label='branch')]),(select id from student_scope where label='student'),'Exact request retry reuses identity');
select throws_ok($$select public.save_student((select id from student_scope where label='tenant'),gen_random_uuid(),null,'{"first_name":"Native student","phone":"998903331111"}','{}',array[(select id from student_scope where label='branch')])$$,'P0001','Possible existing contacts or students: reuse a match or confirm a separate person','Duplicate creation requires review');
select throws_ok($$select public.save_student((select id from student_scope where label='tenant'),gen_random_uuid(),null,'{"first_name":"Invalid student","phone":"998903331112"}','{"education_status":"invalid"}',array[(select id from student_scope where label='branch')])$$,'23514','new row for relation "student_profiles" violates check constraint "student_profiles_education_status_check"','Invalid student rolls back');
select is((select count(*)::integer from public.customers where tenant_id=(select id from student_scope where label='tenant')),1,'Failed student creation leaves no partial contact');
insert into student_scope select 'contact',public.save_customer((select id from student_scope where label='tenant'),null,'{"first_name":"Existing generic contact","phone":"998903331113"}',array[(select id from student_scope where label='branch')]);
select is(public.save_student((select id from student_scope where label='tenant'),gen_random_uuid(),(select id from student_scope where label='contact'),'{"first_name":"Existing generic contact","phone":"998903331113"}','{}',array[(select id from student_scope where label='branch')]),(select id from student_scope where label='contact'),'Contact promotion preserves its original ID');
select is((select count(*)::integer from public.customers where tenant_id=(select id from student_scope where label='tenant')),2,'Promotion adds no duplicate identity');
select is((select count(*)::integer from public.student_profiles where tenant_id=(select id from student_scope where label='tenant')),2,'Both student profiles reference their original contacts');
select is(public.customer_payment_profile((select id from student_scope where label='tenant'),(select id from student_scope where label='student'))->'payment_summary'->>'credit','0.00','Payment adapter reuses exact credit strings');
set local request.jwt.claim.sub='';
select throws_ok($$select public.customer_payment_profile((select id from student_scope where label='tenant'),(select id from student_scope where label='student'))$$,'42501','Contact payment history denied','Subjectless payment overview denied');
select throws_ok($$select public.save_student((select id from student_scope where label='tenant'),gen_random_uuid(),null,'{"first_name":"Denied","phone":"998903331114"}','{}',array[(select id from student_scope where label='branch')])$$,'42501','Student save denied','Subjectless student creation denied');
reset role;select * from finish();rollback;
